#define N normalize

float dM( vec2 c )
{   
    float i, d, p=.5; p=.5*sin(iTime*2.5);

    vec2  z , dz; //c=vec2(-.7,.31);

    for( ; i++<1e2 && dot(z,z)<1024.; )
    {        
		// Z' -> 2·Z·Z' + 1
        dz = 2.*vec2(z.x*dz.x-z.y*dz.y, z.x*dz.y + z.y*dz.x) ;dz.x++;

        // Z -> Z² + c			
        z = vec2( z.x*z.x - z.y*z.y, 2.*z.x*z.y ) + c;		
    }
    // 2023-12-21
    // 这个，f/f'相当于x轴
    // log(r) 把指数级增长化成线性增长
    // distance = |Z|·log|Z|/|Z'| 
	d = //log2(log2(length(z)));
        .5*pow(dot(z,z)/dot(dz,dz),p)*log(dot(z,z));

    //if( i>100) d=0.;

    return d-0.;
}




void mainImage( out vec4 O, vec2 v)
{
    // 
    vec2 R = iResolution.xy,
         u = 1.5 * ((v+v-R)/R.x-vec2(.5,0)),//    *.01-vec2(.75,0.2),
         n,
         e ;e.x=1e-5;

    n = N(  vec2(dM(u+e)-dM(u-e),dM(u+e.yx)-dM(u-e.yx))  );//-dM(u);

    float c=dot(N(vec3(n.x,n.y,.2)),N(vec3(.1,.05,1))) * 2.;

    /*
    float c2=dot(normalize(vec3(n.x,n.y,0.2)),normalize(vec3(.3,.1*u)))/0.5;  
